select json_agg(json_build_object('table', c.relname, 'exact_rows', (xpath('/row/c/text()', query_to_xml(format('select count(*) as c from public.%I', c.relname), false, true, '')))[1]::text::bigint, 'rls', c.relrowsecurity, 'rls_forced', c.relforcerowsecurity, 'owner', pg_get_userbyid(c.relowner), 'comment', obj_description(c.oid, 'pg_class'), 'columns', (select json_agg(json_build_object('name', a.attname, 'type', format_type(a.atttypid, a.atttypmod), 'not_null', a.attnotnull, 'default', pg_get_expr(d.adbin, d.adrelid), 'identity', a.attidentity, 'generated', a.attgenerated) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum where a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped), 'constraints', (select json_agg(json_build_object('name', k.conname, 'type', k.contype, 'def', pg_get_constraintdef(k.oid)) order by k.conname) from pg_constraint k where k.conrelid = c.oid), 'indexes', (select json_agg(pg_get_indexdef(i.indexrelid) order by i.indexrelid) from pg_index i where i.indrelid = c.oid), 'triggers', (select json_agg(pg_get_triggerdef(t.oid)) from pg_trigger t where t.tgrelid = c.oid and not t.tgisinternal), 'policies', (select json_agg(json_build_object('name', p.policyname, 'cmd', p.cmd, 'permissive', p.permissive, 'roles', p.roles, 'qual', p.qual, 'with_check', p.with_check)) from pg_policies p where p.schemaname = 'public' and p.tablename = c.relname), 'grants', (select json_agg(json_build_object('grantee', g.grantee, 'privilege', g.privilege_type)) from information_schema.role_table_grants g where g.table_schema = 'public' and g.table_name = c.relname), 'owned_sequences', (select json_agg(s.relname) from pg_depend dd join pg_class s on s.oid = dd.objid where dd.refobjid = c.oid and s.relkind = 'S' and dd.deptype in ('a','i')), 'dependents_outside_table', (select count(*) from pg_depend dd where dd.refobjid = c.oid and dd.classid <> 'pg_class'::regclass and dd.deptype = 'n' and dd.classid not in ('pg_constraint'::regclass,'pg_trigger'::regclass,'pg_policy'::regclass,'pg_attrdef'::regclass)), 'stats', (select json_build_object('n_tup_ins', s.n_tup_ins, 'n_tup_upd', s.n_tup_upd, 'n_tup_del', s.n_tup_del, 'seq_scan', s.seq_scan, 'idx_scan', s.idx_scan) from pg_stat_user_tables s where s.relid = c.oid)) order by c.relname) as result from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind in ('r','p') and c.relname = any(array['activity_class_economics','ai_model_versions','attribution_summary_cache','content_generation_budget','credential_rotation_attempts','expected_event_definitions','external_api_usage_logs','incident_events','ip_org_creations','job_idempotency_keys','orchestration_attempts','pending_invite_unlocks','sync_jobs','webhook_events']::text[]);